:root {
  --thumb-background: rgba(255, 255, 255, 0.8);
  --img-overlay-background: rgba(70, 140, 255, 0.7);
  --img-overlay-color: #ffffff;
}
.dark-side {
  --thumb-background: rgba(0, 0, 0, 0.8);
}
.img-container,
.img-fluid,
.img-thumbnail {
  width: 100%;
  max-width: 100%;
  height: auto;
  display: block;
  position: relative;
  vertical-align: middle;
  background-color: transparent;
  transition: all 0.3s ease-in-out;
  overflow: visible;
}
.img-thumbnail {
  padding: 0.25rem;
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  background-color: var(--thumb-background);
}
.img-container {
  display: block;
}
.img-container img {
  width: 100%;
  max-width: 100%;
  height: auto;
  position: relative;
}
.img-container .image-overlay {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  opacity: 0;
  overflow: hidden;
  font-size: 0.875rem;
  line-height: 1rem;
  padding: 2em;
  background-color: var(--img-overlay-background);
  color: var(--img-overlay-color);
  text-align: center;
  border-radius: inherit;
  transition: all 0.3s ease-in-out;
}
.img-container .image-overlay * {
  color: inherit;
}
.img-container .image-overlay:hover {
  opacity: 1;
}
.img-container .image-overlay:hover:before,
.img-container .image-overlay:hover:after {
  opacity: 1;
  transform: scale(1);
}
.img-container .image-overlay:before,
.img-container .image-overlay:after {
  display: block;
  position: absolute;
  content: "";
  border: 1px solid var(--border-color);
  top: 1em;
  bottom: 1em;
  left: 1em;
  right: 1em;
  opacity: 0;
  border-radius: inherit;
  transform: scale(1.5);
  transition: all 0.3s ease-in-out;
}
.img-container .image-overlay:after {
  border-left: none;
  border-right: none;
  bottom: 1em;
  top: 1em;
}
.img-container .image-overlay:before {
  border-top: none;
  border-bottom: none;
  bottom: 1em;
  top: 1em;
}
.img-container.rounded img {
  border-radius: var(--border-radius);
}
.img-container.thumbnail {
  padding: 0.25rem;
  border: 1px solid var(--border-color);
  background-color: var(--thumb-background);
}
.img-container.thumbnail .title {
  font-size: 0.9rem;
  line-height: 1;
}
.img-container img + .title {
  margin-top: 0.25rem;
}
.img-container .title + img {
  margin-top: 0.25rem;
}
.img-container.cover {
  background-size: cover;
  background: no-repeat 100% 100%;
}
figure {
  margin: 0 0 1rem;
}
figure img {
  width: 100%;
  max-width: 100%;
  height: auto;
  display: block;
  position: relative;
  vertical-align: middle;
  background-color: transparent;
  transition: all 0.3s ease-in-out;
}
.flip-image-h {
  transform: scaleX(-1);
}
.flip-image-v {
  transform: scaleY(-1);
}
.flip-image {
  transform: scale(-1);
}
