:root {
  --theme-switcher-background: #191919;
  --theme-switcher-color: #ffffff;
  --theme-switcher-border-color: #4c4c4c;
}
.dark-side {
  --theme-switcher-background: #ffffff;
  --theme-switcher-color: #191919;
  --theme-switcher-border-color: #ffffff;
}
.theme-switcher {
  display: inline-flex;
  flex-flow: row nowrap;
  justify-content: flex-start;
  align-items: center;
  position: relative;
  margin: 0;
  user-select: none;
  cursor: pointer;
  height: 36px;
  /* TODO add slide up-down to the theme symbol */
}
.theme-switcher input {
  width: 1px;
  height: 1px;
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
}
.theme-switcher.mode-switch .check {
  line-height: 38px;
  font-size: 14px;
  margin: 0 4px;
  position: relative;
  height: 20px;
  width: 48px;
  border: 2px #1d1d1d solid;
  cursor: pointer;
  background: transparent;
  z-index: 1;
  display: inline-block;
  vertical-align: middle;
  border-radius: 0.5625rem;
  flex-shrink: 0;
}
.theme-switcher.mode-switch .check::before {
  font-family: "Segoe UI Symbol", serif;
  content: attr(data-dark-symbol);
  display: block;
  position: absolute;
  color: inherit;
  left: 16px;
  width: 26px;
  top: -2px;
  line-height: 20px;
  font-size: 10px;
  text-transform: uppercase;
  text-align: center;
}
.theme-switcher.mode-switch .check::after {
  transition: all 0.3s ease-in-out;
  position: absolute;
  left: 3px;
  display: block;
  content: "";
  height: 12px;
  width: 12px;
  top: 50%;
  transform: translateY(-50%);
  border: 2px #333 solid;
  cursor: pointer;
  background: #333;
  z-index: 2;
  border-radius: 50%;
}
.theme-switcher.mode-switch input[type="checkbox"]:indeterminate ~ .check::after {
  background-color: #ccc;
  border-color: #ccc;
  left: auto;
  transform: translateX(18px) translateY(-50%);
}
.theme-switcher.mode-switch input[type="checkbox"]:indeterminate ~ .check::before {
  content: "";
}
.theme-switcher.mode-switch input[type="checkbox"]:checked ~ .check {
  background: #1d1d1d;
  border-color: #1d1d1d;
  color: #1d1d1d;
}
.theme-switcher.mode-switch input[type="checkbox"]:checked ~ .check::after {
  background-color: #ffffff;
  border-color: #ffffff;
  left: auto;
  transform: translateX(30px) translateY(-50%);
}
.theme-switcher.mode-switch input[type="checkbox"]:checked ~ .check::before {
  content: attr(data-light-symbol);
  color: #ffffff;
  left: 1px;
}
.theme-switcher.mode-switch input[type="checkbox"]:disabled ~ .check {
  background-color: #e9e9e9;
  border-color: #e9e9e9;
}
.theme-switcher.mode-switch input[type="checkbox"]:disabled ~ .check::after {
  background-color: #d0d0d0;
  border-color: #d0d0d0;
}
.theme-switcher.mode-switch input[type="checkbox"]:disabled ~ .check::before {
  display: none;
}
.theme-switcher.mode-button {
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  line-height: 24px;
  border-radius: 50%;
  border: 1px solid var(--theme-switcher-border-color);
  cursor: pointer;
  position: relative;
  background: var(--theme-switcher-background);
  color: var(--theme-switcher-color);
  transition: all 0.3s ease-in-out;
  flex-shrink: 0;
}
.theme-switcher.mode-button .check {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  border-radius: 50%;
  width: 100%;
  height: 100%;
}
.theme-switcher.mode-button .check::before,
.theme-switcher.mode-button .check::after {
  font-family: "Segoe UI Symbol", serif;
  content: attr(data-dark-symbol);
  position: relative;
  display: block;
  z-index: 1;
}
.theme-switcher.mode-button .check::before {
  color: #ffffff;
}
.theme-switcher.mode-button .check::after {
  content: attr(data-light-symbol);
  display: none;
}
.theme-switcher.mode-button input:checked + .check::before {
  display: none;
}
.theme-switcher.mode-button input:checked + .check::after {
  display: block;
}
